660: /* clear out the current logical bitstream decoder */
661: static void _decode_clear(OggVorbis_File *vf){
662:   vorbis_dsp_clear(&vf->vd);
663:   vorbis_block_clear(&vf->vb);
664:   vf->ready_state=OPENED;
665: }
