939: static int _ov_open2(OggVorbis_File *vf){
940:   if(vf->ready_state != PARTOPEN) return OV_EINVAL;
941:   vf->ready_state=OPENED;
942:   if(vf->seekable){
943:     int ret=_open_seekable2(vf);
944:     if(ret){
945:       vf->datasource=NULL;
946:       ov_clear(vf);
947:     }
948:     return(ret);
949:   }else
950:     vf->ready_state=STREAMSET;
951: 
952:   return 0;
953: }
