1182:     for(i=0;i<vf->links;i++)
1183:       acc+=ov_raw_total(vf,i);
1184:     return(acc);
1185:   }else{
1186:     return(vf->offsets[i+1]-vf->offsets[i]);
1187:   }
1188: }
