1198:   if(i<0){
1199:     ogg_int64_t acc=0;
1200:     int i;
1201:     for(i=0;i<vf->links;i++)
1202:       acc+=ov_pcm_total(vf,i);
1203:     return(acc);
1204:   }else{
1205:     return(vf->pcmlengths[i*2+1]);
